// Saludo segun la hora real en Madrid, para que la llamada suene natural.
// Convencion en castellano: dias hasta las 14:00, tardes hasta las 21:00,
// y noches a partir de ahi.
const ahora = $now.setZone('Europe/Madrid');
const h = ahora.hour;
const saludo = h < 14 ? 'Buenos días' : (h < 21 ? 'Buenas tardes' : 'Buenas noches');

// Telefono desde el que llaman, por si el flujo lo necesita.
const b = $input.first().json.body || $input.first().json || {};
const llamada = b.call || b;
const telefono = String(llamada.from_number || b.from_number || '').trim();

return [{ json: {
  saludo,
  momento_del_dia: h < 14 ? 'mañana' : (h < 21 ? 'tarde' : 'noche'),
  hora_actual: ahora.toFormat('HH:mm'),
  fecha_actual: ahora.setLocale('es').toFormat("cccc d 'de' LLLL 'de' yyyy"),
  telefono_cliente: telefono,
}}];
